// C++ templates (generics)
template<typename T>
T max(T a, T b) {
    return a > b ? a : b;
}

int    m1 = max(3, 5);      // int
double m2 = max(3.1, 2.7);  // double

// generic container
template<typename T>
class Stack {
    std::vector<T> data;
public:
    void push(T val) { data.push_back(val); }
    T    pop()       { auto v=data.back(); data.pop_back(); return v; }
};
